import{Ct as e,at as t,ct as n,n as r,ot as i,yt as a}from"./chunks/framework.Dkh1x705.js";var o=JSON.parse(`{"title":"YaMapper","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795455254000}`),s={name:`index.md`};function c(r,o,s,c,l,u){let d=e(`SettingsTree`);return a(),t(`div`,null,[o[0]||=i(`<h1 id="yamapper" tabindex="-1">YaMapper <a class="header-anchor" href="#yamapper" aria-label="Permalink to “YaMapper”">​</a></h1><p>Расширение для браузера <a href="https://chromewebstore.google.com/detail/nmapuploader/ohnbeklcgbilmddjahpkmgdlhljgjamd" target="_blank" rel="noreferrer">Crome</a> и <a href="https://addons.mozilla.org/ru/firefox/addon/nmap-uploader/" target="_blank" rel="noreferrer">Firefox</a> которое добавляет разнообразные функции и инструменты в редактор Народной карты Яндекс.</p><h2 id="что-делает-и-для-кого" tabindex="-1">Что делает и для кого <a class="header-anchor" href="#что-делает-и-для-кого" aria-label="Permalink to “Что делает и для кого”">​</a></h2><p>YaMapper убирает барьер между вашими геоданными и редактором Народной карты. Загружайте файлы в привычных форматах, проверяйте и приводите данные в НЯК в порядок, не тратя время на рутинные операции. Дополнительные инструменты расширяют стандартные возможности редактора и делают работу с картой заметно комфортнее.</p><ul><li><p><strong>Для картографов</strong> — Загрузите контур из Shapefile или GeoJSON, и он сразу появится в редакторе, без ручного переноса точек. Накладывайте исторические карты поверх рабочей области и сверяйте наносимый объект с архивными данными, не переключаясь между вкладками.</p></li><li><p><strong>Для модераторов</strong> — Просматривайте свежие правки в ленте истории и фильтруйте удаления, чтобы не пропустить сомнительные изменения. Отслеживайте объекты, которые редактируют пользователи на территории вашей модерации, и сверяйте предлагаемые правки с кадастровыми границами прямо в редакторе.</p></li></ul><p>Расширение работает только на <code>n.maps.yandex.ru</code> и не меняет другие сайты. Геоданные конвертируются локально на вашем устройстве, заметки хранятся на вашем Яндекс.Диске.</p><p><strong>YaMapper не является официальным продуктом Яндекса и никак с ним не связан.</strong></p><h2 id="что-умеет" tabindex="-1">Что умеет <a class="header-anchor" href="#что-умеет" aria-label="Permalink to “Что умеет”">​</a></h2><ul><li><strong><a href="/yamapper/guide/editor/#upload">Загрузка и конвертация</a></strong> — SHP (<code>.zip</code>), GeoJSON, GPX, KML, KMZ, TopoJSON, WKT → Блокнот картографа, по папкам с датой.</li><li><strong><a href="/yamapper/guide/editor/#tracing">Трассировка</a></strong> — загруженный полигон поддерживает штатную «Трассировку» редактора.</li><li><strong><a href="/yamapper/guide/editor/#cut">Разрез растительности и водоёмов</a></strong> — делит линию растительности или водоёма в выбранной точке, с отменой одной командой.</li><li><strong><a href="/yamapper/guide/editor/#split-view">Раздельный вид</a></strong> — редактор и Nakarte в одном окне, с синхронизацией позиции и запоминанием слоёв.</li><li><strong><a href="/yamapper/guide/editor/#notes">Заметки</a></strong> — собственные точки, линии и полигоны с группами, фильтрами и оформлением, поверх загруженных данных.</li><li><strong><a href="/yamapper/guide/editor/#nspd">Загрузка из НСПД</a></strong> — выгрузка границ и объектов из Национальной системы пространственных данных.</li><li><strong><a href="/yamapper/guide/editor/#geo-services">Внешние геосервисы</a></strong> — меню «Перейти» на 2GIS, Google, OSM, Wikimapia, Retromap, ЭтоМесто и другие.</li><li><strong><a href="/yamapper/guide/editor/#point-counter">Счётчик вершин</a></strong> — остаток до лимита 500 вершин, с учётом активной части многочастного объекта.</li><li><strong><a href="/yamapper/guide/moderation/#feeds-filter">Фильтр истории правок</a></strong> — отбор событий ленты по статусу, действию и периоду.</li><li><strong><a href="/yamapper/guide/moderation/#object-tracker">Наблюдение за объектами</a></strong> — история правок выбранных объектов в «Моих объектах».</li><li><strong><a href="/yamapper/guide/style/#stroke-color">Обводка контура</a></strong> — свой цвет обводки у загруженных объектов.</li></ul><h2 id="разделы-настроек" tabindex="-1">Разделы настроек <a class="header-anchor" href="#разделы-настроек" aria-label="Permalink to “Разделы настроек”">​</a></h2><p>Настройки открываются кнопкой-шестерёнкой в шапке редактора. Внутри три вкладки — по ним же разложена справка. Ниже — дерево функций: каждый пункт ведёт на свой раздел, у каждой функции есть отдельная ссылка, которой можно поделиться.</p>`,11),n(d),o[1]||=i(`<h2 id="faq-и-типичные-ошибки" tabindex="-1">FAQ и типичные ошибки <a class="header-anchor" href="#faq-и-типичные-ошибки" aria-label="Permalink to “FAQ и типичные ошибки”">​</a></h2><details class="details custom-block"><summary>«Необходима авторизация. Войдите через Яндекс ID»</summary><p>Расширению нужен доступ к Яндекс Диску, чтобы записать данные об объектах. Нажмите «Войти», разрешите доступ в окне Яндекс ID и повторите загрузку. Если окно закрылось с отказом — включите доступ заново в настройках расширения.</p></details><details class="details custom-block"><summary>Файл загрузился, но в блокноте его нет</summary><p>Обновите страницу, чтобы увидеть свежие данные. Обратите внимание на дату: информация обновляется для выбранного дня, а редактор отображает ту дату, которая указана в его календаре.</p></details><details class="details custom-block"><summary>Не появляется кнопка «Загрузка из НСПД»</summary><p>Проверьте тумблер в разделе <a href="/yamapper/guide/editor/#nspd">«Редактор»</a> и разрешение на домен <code>nspd.gov.ru</code>. Пока доступа нет, в строке настройки показывается кнопка «Разрешить доступ». Выключение тумблера не отзывает уже выданное разрешение.</p></details><details class="details custom-block"><summary>Заметки не загружаются или список пуст</summary><p>Заметки живут в папке <code>Приложения/Nmap Uploader</code> на Яндекс Диске и требуют доступа к Диску. Разрешите доступ по кнопке в панели заметок или в настройках. Если доступа нет, панель покажет «Требуется разрешение» — вход выполнится автоматически после ответа браузера.</p></details><p>Полный список ошибок и решений <a href="/yamapper/guide/faq">тут</a>.</p><h2 id="поддержка" tabindex="-1">Поддержка <a class="header-anchor" href="#поддержка" aria-label="Permalink to “Поддержка”">​</a></h2><p>Нашли ошибку или хотите предложить новую функцию? Отправьте обращение через специальную форму: <a href="/yamapper/suggest">«Предложить улучшение»</a>. Так ваше предложение не потеряется, и я смогу учесть его в планах развития.</p><p>Если нужно связаться напрямую, напишите автору в Telegram: @stylesvoboda или в личные сообщения в Яндекс Мессенджере.</p>`,9)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};